CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

CREATE TABLE "Amenities" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    CONSTRAINT "PK_Amenities" PRIMARY KEY ("Id")
);

CREATE TABLE "AuditLogs" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CreatedAt" timestamp without time zone NOT NULL,
    "UserId" integer,
    "UserName" character varying(100) NOT NULL,
    "Role" character varying(20) NOT NULL,
    "Action" character varying(50) NOT NULL,
    "EntityType" character varying(50) NOT NULL,
    "EntityId" integer NOT NULL,
    "Details" character varying(500),
    CONSTRAINT "PK_AuditLogs" PRIMARY KEY ("Id")
);

CREATE TABLE "Coupons" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" character varying(20) NOT NULL,
    "DiscountType" character varying(10) NOT NULL,
    "Value" numeric(18,2) NOT NULL,
    "MaxDiscount" numeric(18,2),
    "MinBookingAmount" numeric(18,2) NOT NULL,
    "ValidFrom" timestamp without time zone NOT NULL,
    "ValidTo" timestamp without time zone NOT NULL,
    "MaxUses" integer,
    "UsedCount" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    "RowVersion" bytea NOT NULL,
    CONSTRAINT "PK_Coupons" PRIMARY KEY ("Id")
);

CREATE TABLE "Customers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FullName" text NOT NULL,
    "Email" text NOT NULL,
    "Phone" text,
    "IsDeleted" boolean NOT NULL,
    "DeletedAt" timestamp without time zone,
    CONSTRAINT "PK_Customers" PRIMARY KEY ("Id")
);

CREATE TABLE "ExtraServices" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "Price" numeric(18,2) NOT NULL,
    "Unit" character varying(30) NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_ExtraServices" PRIMARY KEY ("Id")
);

CREATE TABLE "RoomTypes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Description" text,
    "PricePerNight" numeric(18,2) NOT NULL,
    "Capacity" integer NOT NULL,
    CONSTRAINT "PK_RoomTypes" PRIMARY KEY ("Id")
);

CREATE TABLE "Users" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Username" text NOT NULL,
    "PasswordHash" text NOT NULL,
    "Role" text NOT NULL,
    "CustomerId" integer,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Users_Customers_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "Customers" ("Id")
);

CREATE TABLE "PricingRules" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "RuleType" character varying(10) NOT NULL,
    "StartDate" timestamp without time zone,
    "EndDate" timestamp without time zone,
    "RoomTypeId" integer,
    "Percent" numeric(5,2) NOT NULL,
    "Priority" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_PricingRules" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PricingRules_RoomTypes_RoomTypeId" FOREIGN KEY ("RoomTypeId") REFERENCES "RoomTypes" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Rooms" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RoomNumber" text NOT NULL,
    "Status" text NOT NULL,
    "RoomTypeId" integer NOT NULL,
    "Floor" integer NOT NULL DEFAULT 1,
    "Description" character varying(500),
    "ImageUrl" character varying(500),
    "IsDeleted" boolean NOT NULL,
    "DeletedAt" timestamp without time zone,
    CONSTRAINT "PK_Rooms" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Rooms_RoomTypes_RoomTypeId" FOREIGN KEY ("RoomTypeId") REFERENCES "RoomTypes" ("Id") ON DELETE CASCADE
);

CREATE TABLE "RefreshTokens" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "TokenHash" character varying(100) NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    "ExpiresAt" timestamp without time zone NOT NULL,
    "RevokedAt" timestamp without time zone,
    CONSTRAINT "PK_RefreshTokens" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_RefreshTokens_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AmenityRoom" (
    "AmenitiesId" integer NOT NULL,
    "RoomsId" integer NOT NULL,
    CONSTRAINT "PK_AmenityRoom" PRIMARY KEY ("AmenitiesId", "RoomsId"),
    CONSTRAINT "FK_AmenityRoom_Amenities_AmenitiesId" FOREIGN KEY ("AmenitiesId") REFERENCES "Amenities" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_AmenityRoom_Rooms_RoomsId" FOREIGN KEY ("RoomsId") REFERENCES "Rooms" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Bookings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CustomerId" integer NOT NULL,
    "RoomId" integer NOT NULL,
    "CheckInDate" timestamp without time zone NOT NULL,
    "CheckOutDate" timestamp without time zone NOT NULL,
    "TotalPrice" numeric(18,2) NOT NULL,
    "CouponId" integer,
    "DiscountAmount" numeric(18,2) NOT NULL,
    "Status" text NOT NULL,
    "CheckedInAt" timestamp without time zone,
    "CheckedOutAt" timestamp without time zone,
    "RowVersion" bytea NOT NULL,
    CONSTRAINT "PK_Bookings" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Bookings_Coupons_CouponId" FOREIGN KEY ("CouponId") REFERENCES "Coupons" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Bookings_Customers_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "Customers" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Bookings_Rooms_RoomId" FOREIGN KEY ("RoomId") REFERENCES "Rooms" ("Id") ON DELETE CASCADE
);

CREATE TABLE "BookingExtraServices" (
    "BookingId" integer NOT NULL,
    "ExtraServiceId" integer NOT NULL,
    "Quantity" integer NOT NULL,
    "UnitPrice" numeric(18,2) NOT NULL,
    CONSTRAINT "PK_BookingExtraServices" PRIMARY KEY ("BookingId", "ExtraServiceId"),
    CONSTRAINT "FK_BookingExtraServices_Bookings_BookingId" FOREIGN KEY ("BookingId") REFERENCES "Bookings" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_BookingExtraServices_ExtraServices_ExtraServiceId" FOREIGN KEY ("ExtraServiceId") REFERENCES "ExtraServices" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "PaymentClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BookingId" integer NOT NULL,
    "Amount" numeric(18,2) NOT NULL,
    "Method" character varying(20) NOT NULL,
    "Note" character varying(500),
    "Status" character varying(20) NOT NULL,
    "CustomerConfirmedAt" timestamp without time zone NOT NULL,
    "CashierReviewedAt" timestamp without time zone,
    "CashierUserId" integer,
    "CashierNote" character varying(500),
    CONSTRAINT "PK_PaymentClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PaymentClaims_Bookings_BookingId" FOREIGN KEY ("BookingId") REFERENCES "Bookings" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Payments" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BookingId" integer NOT NULL,
    "Amount" numeric(18,2) NOT NULL,
    "Type" character varying(10) NOT NULL,
    "Method" character varying(20) NOT NULL,
    "Note" character varying(500),
    "CreatedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_Payments" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Payments_Bookings_BookingId" FOREIGN KEY ("BookingId") REFERENCES "Bookings" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Reviews" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BookingId" integer NOT NULL,
    "RoomId" integer NOT NULL,
    "CustomerId" integer NOT NULL,
    "Rating" integer NOT NULL,
    "Comment" character varying(1000),
    "CreatedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_Reviews" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Reviews_Bookings_BookingId" FOREIGN KEY ("BookingId") REFERENCES "Bookings" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Reviews_Customers_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "Customers" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Reviews_Rooms_RoomId" FOREIGN KEY ("RoomId") REFERENCES "Rooms" ("Id") ON DELETE RESTRICT
);

