CREATE INDEX "IX_AmenityRoom_RoomsId" ON "AmenityRoom" ("RoomsId");

CREATE INDEX "IX_AuditLogs_EntityType_EntityId" ON "AuditLogs" ("EntityType", "EntityId");

CREATE INDEX "IX_BookingExtraServices_ExtraServiceId" ON "BookingExtraServices" ("ExtraServiceId");

CREATE INDEX "IX_Bookings_CouponId" ON "Bookings" ("CouponId");

